    "torch::Tensor transposed_conv_kernel(torch::Tensor input, torch::Tensor output, int batch_size, int in_channels, int out_channels, int kernel_size, int stride, int padding, int dilation);"
)

# Load the custom CUDA operator
transposed_conv = load_inline(
    name="transposed_conv",
    cpp_sources=transposed_conv_cpp_source,
    cuda_sources=transposed_conv_kernel,
    functions=["transposed_conv_kernel"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

