class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        # Initialize the transposed convolution layer
        self.transposed_conv = torch.nn.TransposeConvolution2d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            dilation=dilation,
            bias=bias,
            device="cuda",
            dtype=torch.float32
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the 2D transposed convolution.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, height_in, width_in). 

        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_channels, height_out, width_out).
        """
        return self.transposed_conv(x)

# Example usage
if __name__ == "__main__":
    # Create a simple test case
    batch_size = 16
    in_channels = 32
    out_channels = 64
    kernel_size = 3
    stride = 5
    padding = 1
    dilation = 2

    model = ModelNew(in_channels, out_channels, kernel_size, stride, padding, dilation, bias=False)

    # Create a dummy input tensor
    x = torch.rand(batch_size, in_channels, 64, 128).cuda()

    # Forward pass
    output = model(x)
    print("Output shape:", output.shape)
